#!/usr/bin/env python3
"""Uruk LifeHub executive proposal, edition 3.
One idea per slide, one grid, one glass component, one accent. Arabic first.
All information from the source deck is preserved; no dash characters."""
from pathlib import Path
import re

HERE = Path(__file__).parent
OUT = HERE / "deck-v3.html"
SLIDES = []


def en(t):
    return f'<span class="en">{t}</span>'


def n(t):
    return f'<span class="n">{t}</span>'


MARK = '''<svg width="30" height="30" viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="19" stroke="currentColor" stroke-opacity=".25" stroke-width="1.2"/><path d="M6 22a14 8 0 1 0 28 0" stroke="currentColor" stroke-opacity=".55" stroke-width="1.2" stroke-linecap="round"/><rect x="9" y="25" width="22" height="4" rx="1" fill="currentColor"/><rect x="13" y="19" width="14" height="4" rx="1" fill="currentColor"/><rect x="17" y="13" width="6" height="4" rx="1" fill="currentColor"/></svg>'''


def slide(section, title, sub, body, closing, cls="", kicker=""):
    i = len(SLIDES) + 1
    head = "" if cls == "cover" else f'''<div class="head"><div class="head-r">{f'<div class="kicker">{kicker}</div>' if kicker else ''}<h1>{title}</h1>{f'<p class="sub">{sub}</p>' if sub else ''}</div></div>'''
    SLIDES.append(f'''<section class="slide {cls}" data-i="{i}">
<div class="glow"><i class="g1"></i><i class="g2"></i></div>
<header class="top"><div class="idx"><b>{i:02d}</b><span>{section}</span></div><div class="brand">{MARK}<div><b>URUK LIFEHUB</b><small>بتشغيل وإدارة {en("Aspire Gate")}</small></div></div></header>
{head}
<main class="body">{body}</main>
<footer class="foot"><span>{closing}</span><span class="pg">{i:02d}</span></footer>
</section>''')


def tile(num, title, desc="", cls=""):
    ring = f'<span class="ring">{num}</span>' if num else ""
    return f'<div class="tile {cls}">{ring}<b>{title}</b>{f"<p>{desc}</p>" if desc else ""}</div>'


def tiles(items, cls=""):
    return f'<div class="grid {cls}">' + "".join(tile(k + 1, t, d) for k, (t, d) in enumerate(items)) + '</div>'


def panel(label, html, cls=""):
    return f'<div class="panel {cls}">{f"<div class=lbl>{label}</div>" if label else ""}{html}</div>'


def statement(kicker, title, lead="", extra=""):
    return f'<div class="statement">{f"<div class=kicker>{kicker}</div>" if kicker else ""}<h2>{title}</h2>{f"<p>{lead}</p>" if lead else ""}{extra}</div>'


def chain(items):
    out = []
    for k, (t, d) in enumerate(items):
        out.append(f'<div class="step"><span class="ring">{k + 1 if t != "∞" else "∞"}</span><b>{t if t != "∞" else "العودة"}</b>{f"<p>{d}</p>" if d else ""}</div>')
        if k < len(items) - 1:
            out.append('<i class="chev"></i>')
    return '<div class="chain">' + "".join(out) + '</div>'


def passport():
    return f'''<div class="pcard"><div class="pc-top">{MARK}<span class="nfc"><i></i><i></i><i></i></span></div>
<div class="pc-name">URUK<br>EDUCATION<br>PASSPORT</div>
<div class="pc-foot"><div><small>GLOBAL LEARNING ID</small><b>MEMBER</b></div><span class="chip"></span></div></div>'''


